/* ---------- відгуки ---------- */
INSERT INTO dbo.Reviews (MovieId, UserId, Rating, [Text])
SELECT m.Id, u.Id, v.rating, v.txt
FROM (VALUES
  (N'Довженко',   N'oleksiy.k@example.com', 5, N'Чудовий фільм! Сюжет захоплює з першої хвилини і не відпускає до самого кінця.'),
  (N'Довженко',   N'maria.s@example.com',   4, N'Гарна робота акторів та режисера. Рекомендую до перегляду!'),
  (N'Довженко',   N'iryna.p@example.com',   5, N'Атмосферно, красиво знято. Дуже сподобалась музика.'),
  (N'Оппенгеймер', N'oleksiy.k@example.com', 5, N'Сильна драма з потужною акторською грою.'),
  (N'Оппенгеймер', N'maria.s@example.com',   4, N'Довгий, але не нудний: тримає в напрузі до фіналу.'),
  (N'Чародійка',  N'iryna.p@example.com',   5, N'Яскравий мюзикл, чудова музика й візуал.'),
  (N'Аватар: Шлях води', N'maria.s@example.com', 4, N'Неймовірна графіка, особливо в залі з Dolby Atmos.')
) v(title, email, rating, txt)
JOIN dbo.Movies m ON m.Title = v.title
JOIN dbo.Users  u ON u.Email = v.email;

SELECT (SELECT COUNT(*) FROM dbo.Movies)  AS Movies,
       (SELECT COUNT(*) FROM dbo.Users)   AS Users,
       (SELECT COUNT(*) FROM dbo.Reviews) AS Reviews;